function processSentence(sentence) {
  // Split the sentence into words
  const words = sentence.split(' ');

  // Initialize an empty array to store the processed words
  const processedWords = [];

  // Iterate through each word
  for (let i = 0; i < words.length; i++) {
    // Check if the word starts with 'S'
    if (words[i][0].toUpperCase() === 'S') {
      // If it does, capitalize the first letter and add '!' at the end
      processedWords.push(words[i].charAt(0).toUpperCase() + words[i].slice(1) + '!');
    } else {
      // If not, just add the word as is
      processedWords.push(words[i]);
    }
  }

  // Join the processed words back into a sentence
  const processedSentence = processedWords.join(' ');

  // Return the processed sentence
  return processedSentence;
}

// Test the function
const sentence = "The quick brown fox jumps over the lazy dog";
console.log(processSentence(sentence));
